import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { useNavigate } from "react-router-dom";

export default function Match() {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [loading, setLoading] = useState(false);
  const [matchLogs, setMatchLogs] = useState([]);
  const [playerProfiles, setPlayerProfiles] = useState({});
  const navigate = useNavigate();

  const stompClientRef = useRef(null);
  const pollingRef = useRef(null);
  const timeoutRef = useRef(null);
  const logPollingRef = useRef(null);

  const ALLOWED_FEES = [13, 23, 50];
  const token = localStorage.getItem("authToken");

  // প্রোফাইল ফেচ করার হেল্পার
  const fetchPlayerProfile = async (gameId) => {
    try {
      const res = await axios.get(`http://localhost:8080/api/user/profile/${gameId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return res.data;
    } catch (e) {
      console.error("Profile fetch error for", gameId, e);
      return null;
    }
  };

  // আগের ম্যাচ চেক করা
  useEffect(() => {
    axios
      .get("http://localhost:8080/api/match/status", {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        if (res.data?.gameId) {
          setGame(res.data);
          setStatus("⚠️ আগের ম্যাচ পাওয়া গেছে, যুক্ত হচ্ছি...");
        } else {
          setStatus("কোনো ম্যাচ পাওয়া যায়নি");
        }
      })
      .catch(() => setStatus("API error হয়েছে"));
  }, []);

  // WebSocket কানেকশন
  useEffect(() => {
    if (!game?.gameId) return;

    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: (str) => console.log("[STOMP]", str),
      onConnect: () => {
        console.log("WebSocket connected");

        [game.player1, game.player2].forEach((player) => {
          if (player) {
            client.subscribe(`/topic/match/${player}`, (message) => {
              handleMatchMessage(message);
            });
          }
        });
      },
    });
    client.activate();
    stompClientRef.current = client;

    return () => client.deactivate();
  }, [game]);

  // WS মেসেজ হ্যান্ডলার
  const handleMatchMessage = async (message) => {
    try {
      const payload = JSON.parse(message.body);

      if (payload.status === "CANCELLED") {
        setStatus("❌ ম্যাচ বাতিল হয়েছে");
        return;
      }

      if (payload.player1 && payload.player2) {
        // প্রোফাইল ডেটা লোড
        const p1 = await fetchPlayerProfile(payload.player1);
        const p2 = await fetchPlayerProfile(payload.player2);
        setPlayerProfiles({
          [payload.player1]: p1,
          [payload.player2]: p2,
        });

        // লোকালস্টোরেজ সেট
        localStorage.setItem("currentSessionId", payload.gameId);
        localStorage.setItem("entryFee", payload.entryFee);

        // সরাসরি গেমে নিয়ে যাওয়া
        navigate("/game");
      }

      if (payload.logs) {
        setMatchLogs((prevLogs) => [...prevLogs, ...payload.logs]);
      }
    } catch (e) {
      console.error("WS parse error", e);
    }
  };

  // ম্যাচ রিকোয়েস্ট
  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(entryFee)) {
      setStatus("❌ সঠিক এন্ট্রি ফি সিলেক্ট করুন");
      return;
    }
    setLoading(true);
    setStatus("");

    try {
      await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        { headers: { Authorization: `Bearer ${token}` } }
      );
    } catch {
      setStatus("ম্যাচ শুরু করতে সমস্যা হয়েছে");
      setLoading(false);
      return;
    }

    pollingRef.current = setInterval(async () => {
      try {
        const res = await axios.get("http://localhost:8080/api/match/status", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.data?.gameId) {
          clearInterval(pollingRef.current);
          setGame(res.data);

          // প্রোফাইল ফেচ
          const p1 = await fetchPlayerProfile(res.data.player1);
          const p2 = await fetchPlayerProfile(res.data.player2);
          setPlayerProfiles({
            [res.data.player1]: p1,
            [res.data.player2]: p2,
          });

          setLoading(false);
        }
      } catch (e) {
        console.error("Polling error:", e);
      }
    }, 3000);

    timeoutRef.current = setTimeout(() => {
      clearInterval(pollingRef.current);
      setStatus("⏳ ৩০ মিনিটে প্রতিপক্ষ পাওয়া যায়নি");
      setLoading(false);
    }, 30 * 60 * 1000);
  };

  // ম্যাচ লগস পোলিং
  useEffect(() => {
    if (!game?.gameId) return;

    const fetchMatchLogs = async () => {
      try {
        const res = await axios.get(
          `http://localhost:8080/api/match/status/${game.gameId}`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        if (res.data?.logs) {
          setMatchLogs(res.data.logs);
        }
      } catch (e) {
        console.error("Match logs fetch error:", e);
      }
    };

    fetchMatchLogs();
    logPollingRef.current = setInterval(fetchMatchLogs, 10000);
    return () => clearInterval(logPollingRef.current);
  }, [game]);

  // ক্লিনআপ
  useEffect(() => {
    return () => {
      clearInterval(pollingRef.current);
      clearTimeout(timeoutRef.current);
      clearInterval(logPollingRef.current);
      if (stompClientRef.current) {
        stompClientRef.current.deactivate();
      }
    };
  }, []);

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-indigo-900 via-purple-800 to-indigo-900 p-6">
      <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 w-full max-w-md shadow-xl border border-white/20">
        <h2 className="text-3xl font-bold text-center text-white mb-6">🎲 লুডু ম্যাচ</h2>

        {/* প্রোফাইল কার্ড */}
        {Object.keys(playerProfiles).length > 0 && (
          <div className="flex justify-around mb-6">
            {Object.values(playerProfiles).map((p, idx) => (
              p && (
                <div key={idx} className="flex flex-col items-center">
                  <img
                    src={p.avatarUrl || "/default-avatar.png"}
                    alt="avatar"
                    className="w-16 h-16 rounded-full border-2 border-yellow-400 mb-2"
                  />
                  <span className="text-white">{p.displayName || p.gameId}</span>
                </div>
              )
            ))}
          </div>
        )}

        <label className="block text-white text-lg mb-2">এন্ট্রি ফি</label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full p-3 rounded-lg bg-white/20 text-white border border-white/30 focus:outline-none focus:ring-2 focus:ring-yellow-400 mb-4"
        >
          {ALLOWED_FEES.map((f) => (
            <option key={f} value={f} className="text-black">
              ৳ {f}
            </option>
          ))}
        </select>

        <button
          onClick={handleMatchRequest}
          disabled={loading}
          className={`w-full py-3 rounded-lg font-semibold text-lg transition-all duration-300 ${
            loading
              ? "bg-yellow-500 cursor-not-allowed"
              : "bg-yellow-400 hover:bg-yellow-500 text-black"
          }`}
        >
          {loading ? "⏳ খোঁজা হচ্ছে..." : "🔍 প্রতিপক্ষ খুঁজুন"}
        </button>

        {status && <p className="mt-4 text-center text-white font-medium">{status}</p>}

        {/* ম্যাচ লগ */}
        {matchLogs.length > 0 && (
          <div className="mt-6 max-h-40 overflow-y-auto bg-black/30 p-3 rounded-md text-white text-sm">
            <h3 className="font-semibold mb-2">ম্যাচ লগস:</h3>
            {matchLogs.map((log, i) => (
              <p key={i} className="border-b border-white/20 py-1">
                {typeof log === "string" ? log : JSON.stringify(log)}
              </p>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
